import { createServerFn } from "@tanstack/react-start";
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";
import type { Database } from "@/integrations/supabase/types";

// The database types are generated by Lovable. Until regenerated, this new,
// tightly restricted table is accessed through the unparameterized client type.
export type TesterApplication = {
  id: string;
  email: string;
  platform: "android" | "ios" | "both" | "web";
  participation: "technical" | "everyday" | "both";
  focus: "planning" | "energy" | "capture" | "recovery" | "overview" | "general";
  feedback_willing: boolean;
  language: "sv" | "en";
  confirmation_accepted_at: string | null;
  admin_notice_accepted_at: string | null;
  status: "new" | "invited" | "testing" | "complete";
  created_at: string;
};

const submission = z.object({
  email: z.string().trim().toLowerCase().email().max(254),
  platform: z.enum(["android", "ios", "both", "web"]),
  participation: z.enum(["technical", "everyday", "both"]),
  focus: z.enum(["planning", "energy", "capture", "recovery", "overview", "general"]),
  feedback_willing: z.boolean(),
  language: z.enum(["sv", "en"]).default("sv"),
  adult: z.literal(true),
  consent: z.literal(true),
  // A hidden honeypot; real visitors should never fill this in.
  company: z.string().max(200).optional().default(""),
});

const recordId = z.object({ id: z.string().uuid() });
const updateStatus = recordId.extend({
  status: z.enum(["new", "invited", "testing", "complete"]),
});

/** No user account required. The browser never receives the service-role key. */
export const submitTesterApplicationFn = createServerFn({ method: "POST" })
  .inputValidator((input: unknown) => submission.parse(input))
  .handler(async ({ data }): Promise<{ ok: true }> => {
    if (data.company.trim()) return { ok: true }; // silently discard spam
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const db = supabaseAdmin as unknown as SupabaseClient;
    const { data: inserted, error } = await db
      .from("tester_applications")
      .insert({
        email: data.email,
        platform: data.platform,
        participation: data.participation,
        focus: data.focus,
        feedback_willing: data.feedback_willing,
        language: data.language,
        consent_version: 1,
      })
      .select(
        "id, email, platform, participation, focus, feedback_willing, language, confirmation_accepted_at, admin_notice_accepted_at",
      )
      .single();
    // Duplicate email must not reveal who is registered or trigger another mail.
    if (error?.code === "23505") return { ok: true };
    if (error || !inserted) {
      throw new Error("Anmälan kunde inte sparas just nu. Försök igen senare.");
    }

    // The application was saved. Email is a best-effort follow-up, never
    // a reason to tell the person their application failed.
    try {
      const { sendTesterSignupEmails } = await import("@/lib/tester-recruitment-mail.server");
      await sendTesterSignupEmails(
        db,
        inserted as import("@/lib/tester-recruitment-mail.server").MailApplicant,
      );
    } catch {
      console.warn("[tester-email] confirmation/notification could not be started");
    }
    return { ok: true };
  });

/** Every admin read/write is authenticated and role-checked on the server. */
async function assertAdmin(supabase: SupabaseClient<Database>, userId: string) {
  const { data, error } = await supabase
    .from("user_roles")
    .select("role")
    .eq("user_id", userId)
    .eq("role", "admin")
    .maybeSingle();
  if (error || !data) throw new Error("Forbidden");
}

export const listTesterApplicationsFn = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }): Promise<TesterApplication[]> => {
    await assertAdmin(context.supabase, context.userId);
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { data, error } = await (supabaseAdmin as unknown as SupabaseClient)
      .from("tester_applications")
      .select(
        "id, email, platform, participation, focus, feedback_willing, language, confirmation_accepted_at, admin_notice_accepted_at, status, created_at",
      )
      .order("created_at", { ascending: false })
      .limit(500);
    if (error) throw new Error("Kunde inte läsa testanmälningarna.");
    return (data ?? []) as TesterApplication[];
  });

export const updateTesterApplicationFn = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((input: unknown) => updateStatus.parse(input))
  .handler(async ({ context, data }) => {
    await assertAdmin(context.supabase, context.userId);
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { error } = await (supabaseAdmin as unknown as SupabaseClient)
      .from("tester_applications")
      .update({ status: data.status, updated_at: new Date().toISOString() })
      .eq("id", data.id);
    if (error) throw new Error("Kunde inte uppdatera testanmälan.");
    return { ok: true };
  });

export const deleteTesterApplicationFn = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((input: unknown) => recordId.parse(input))
  .handler(async ({ context, data }) => {
    await assertAdmin(context.supabase, context.userId);
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { error } = await (supabaseAdmin as unknown as SupabaseClient)
      .from("tester_applications")
      .delete()
      .eq("id", data.id);
    if (error) throw new Error("Kunde inte radera testanmälan.");
    return { ok: true };
  });

/** Admin-only manual retry for missing confirmations; also handles pre-existing signups. */
export const retryTesterApplicationEmailsFn = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((input: unknown) => recordId.parse(input))
  .handler(async ({ context, data }) => {
    await assertAdmin(context.supabase, context.userId);
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const db = supabaseAdmin as unknown as SupabaseClient;
    const { data: row, error } = await db
      .from("tester_applications")
      .select(
        "id, email, platform, participation, focus, feedback_willing, language, confirmation_accepted_at, admin_notice_accepted_at",
      )
      .eq("id", data.id)
      .single();
    if (error || !row) throw new Error("Anmälan finns inte kvar.");
    const { sendTesterSignupEmails } = await import("@/lib/tester-recruitment-mail.server");
    const result = await sendTesterSignupEmails(
      db,
      row as import("@/lib/tester-recruitment-mail.server").MailApplicant,
    );
    return result;
  });
